import type { Rel as UsdRel } from 'typescript-usd/usd'
import { TfEnvSetting, TfGetEnvSetting, TfStringStartsWith, TfStringTokenize, Type as TfType } from 'typescript-usd/tf'
import { ValueTypeNames } from 'typescript-usd/sdf'
import { SdfPath } from 'typescript-usd/sdf/path'
import { PrimvarsAPI } from 'typescript-usd/usdGeom'
import { UsdRi_GetUsdType } from './typeUtils.ts'

// statementsAPI.cpp:122-125.
export const USDRI_STATEMENTS_READ_OLD_ATTR_ENCODING = new TfEnvSetting(
  'USDRI_STATEMENTS_READ_OLD_ATTR_ENCODING', true,
  'If on, UsdRiStatementsAPI will read old-style attributes.  ' +
  'Otherwise, primvars in the ri: namespace will be read instead.')

// statementsAPI.cpp:127-137.
const _tokens = Object.freeze({
  fullAttributeNamespace: 'ri:attributes:',
  primvarAttrNamespace: 'primvars:ri:attributes:',
  rootNamespace: 'ri',
  attributeNamespace: 'attributes',
  coordsys: 'ri:coordinateSystem',
  scopedCoordsys: 'ri:scopedCoordinateSystem',
  modelCoordsys: 'ri:modelCoordinateSystems',
  modelScopedCoordsys: 'ri:modelScopedCoordinateSystems',
})

// statementsAPI.cpp:139-144.
function _makeRiAttrNamespace(nameSpace: string, attrName: string): string {
  return _tokens.fullAttributeNamespace + nameSpace + ':' + attrName
}

// UsdObject::GetName of an attribute or relationship handle.
function _propName(prop: Attribute | UsdRel): string {
  return prop.name
}

// UsdProperty::GetBaseName (property.cpp): the last namespace component.
function _baseName(name: string): string {
  return name.slice(name.lastIndexOf(':') + 1)
}

// UsdProperty::IsAuthored (property.cpp): any spec for the property in the
// prim's layer stack.
function _isAuthored(stage: Stage, prop: Attribute | UsdRel): boolean {
  return stage.getPropertyStack(prop.getPath()).length > 0
}

// UsdPrim::GetPropertiesInNamespace (prim.cpp): the properties, builtin and
// authored, whose names begin with the namespace.
function _getPropertiesInNamespace(prim: Prim, namespaces: string): (Attribute | UsdRel)[] {
  const out: (Attribute | UsdRel)[] = []
  for (const name of prim.getPropertyNames(n => n.startsWith(namespaces))) {
    const prop = prim.getStage().getPropertyAtPath(`${prim.path}.${name}`)
    if (prop) out.push(prop)
  }
  return out
}

// UsdPrim::GetParent.
function _getParent(prim: Prim): Prim | undefined {
  if (prim.path === '/') return undefined
  return prim.getStage().getPrim(SdfPath.fromString(prim.path).getParentPath().pathString)
}
